:root {
  /* ==========================================
     全局基础设定：底栏、输入框
     ========================================== */
  /* 底栏背景颜色 */
  --input-area-bg: #F1F1F1;

  /* 输入框背景白色、去掉边框、方圆 */
  --input-box-bg: #FFFFFF;
  --input-box-border: none;
  --input-box-radius: 10px; 
}

/* ==========================================
   清空原有的胶囊限制，腾出两排的空间
   ========================================== */
.input-area-custom {
  padding: 0 !important;
}
.input-row-wrapper {
  position: relative !important;
  display: block !important;
  min-height: 110px !important; 
}
.input-btns-right {
  position: static !important;
}

/* 强制隐藏输入框的占位符 */
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

/* ==========================================
   第一排：纯白方圆输入框 + AI按钮
   ========================================== */
.input-action-bar-custom {
  position: absolute !important;
  background-color: #FFFFFF !important;
  border-radius: 12px !important;   
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;     

  left: 15px !important; 
  top: 10px !important;
  width: 78% !important; 
  height: 42px !important; 

  padding: 0 !important;
  margin: 0 !important;
}

.input-box-custom {
  position: absolute !important;
  left: 0 !important;
  top: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background: transparent !important; 
  border: none !important;
  box-shadow: none !important;
  padding: 10px 15px !important;
  box-sizing: border-box !important;
}

/* 💥 强行杀掉自带图标 💥 */
.input-btn-ai *, .send-btn-custom *, .input-btn-plus *, .input-btn-mic *, .input-btn-sticker * {
  display: none !important;
}

/* ==========================================
   1. AI 按钮 (右侧) —— 遮罩染色魔法
   ========================================== */
.input-btn-ai, .send-btn-custom {
  position: absolute !important;
  width: 40px !important;   
  height: 40px !important;
  background: transparent !important; 
  overflow: visible !important; 

  right: -54px !important;  
  top: 1px !important;      
}

.input-btn-ai::after, .send-btn-custom::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%); 

  /* 💥 使用 Mask 技术强行给图片染上 FDEBF0 颜色 💥 */
  background-color: #FDEBF0 !important; 
  -webkit-mask-image: url('https://img.heliar.top/file/1779100630944_retouch_2026051817072255.png');
  -webkit-mask-size: contain;
  -webkit-mask-position: center;
  -webkit-mask-repeat: no-repeat;
  background-image: none !important;

  width: 60px; 
  height: 35px;
}

/* ==========================================
   2. 加号按钮 (左下角)
   ========================================== */
.input-btn-plus {
  position: absolute !important;
  margin: 0 !important;
  width: 40px !important;
  height: 40px !important;
  background: transparent !important;
  overflow: visible !important;

  left: 17px !important;    
  top: 61px !important;     
}

.input-btn-plus::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background-image: url('https://img.heliar.top/file/1779099675757_retouch_2026051817012903.png');
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;

  width: 23px;
  height: 23px;
}

/* ==========================================
   3. 装饰贴图（它本来就没点击区，不用分离）
   ========================================== */
.input-row-wrapper::before {
  content: "";
  position: absolute;
  background: url('https://img.heliar.top/file/1779099679511_retouch_2026051817052301.png') no-repeat center/contain;
  pointer-events: none;
  z-index: 10;

  left: 90px;   
  top: 38px;    
  width: 160px;  
  height: 90px;
}

/* ==========================================
   4. 语音按钮
   ========================================== */
.input-btn-mic {
  position: absolute !important;
  margin: 0 !important;
  width: 40px !important;
  height: 40px !important;
  background: transparent !important;
  overflow: visible !important;

  left: 275px !important;   
  top: 54px !important;    
}

.input-btn-mic::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background-image: url('https://img.heliar.top/file/1779099549238_retouch_2026051817063690.png');
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;

  width: 23px;
  height: 23px;
}

/* ==========================================
   5. 表情按钮
   ========================================== */
.input-btn-sticker {
  position: absolute !important;
  margin: 0 !important;
  width: 40px !important;
  height: 40px !important;
  background: transparent !important;
  overflow: visible !important;

  left: 340px !important;  
  top: 54px !important;    
}

.input-btn-sticker::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background-image: url('https://img.heliar.top/file/1779099554667_retouch_2026051817070027.png');
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;

  width: 23px;
  height: 23px;
}

/* ==========================================

  /* 转账气泡颜色适配 */
  --transfer-card-bg: #0099FF;
  --transfer-card-border: none;

  /* 我方转账变成粉色+深色字适配 */
  --transfer-me-card-bg: #FDEBF0;
  --transfer-me-amount-color: #262626;
  --transfer-me-label-color: rgba(0, 0, 0, 0.6);
  --transfer-me-subtitle-color: rgba(0, 0, 0, 0.5);
  --transfer-me-status-color: rgba(0, 0, 0, 0.6);
  --transfer-me-divider-color: rgba(0, 0, 0, 0.1);
  --transfer-me-icon-bg: rgba(0, 0, 0, 0.05);

  --transfer-them-card-bg: #0099FF;
  --transfer-them-amount-color: #FFFFFF;
  --transfer-them-label-color: rgba(255, 255, 255, 0.9);
  --transfer-them-subtitle-color: rgba(255, 255, 255, 0.7);
  --transfer-them-status-color: rgba(255, 255, 255, 0.9);
  --transfer-them-divider-color: rgba(255, 255, 255, 0.2);
  --transfer-them-icon-bg: rgba(255, 255, 255, 0.25);

  /* 强制取消阴影和边框 */
  --bubble-me-shadow: none;
  --bubble-them-shadow: none;
  --bubble-them-border: none;
}

.bubble-me-custom,
.bubble-them-custom {
  box-shadow: none !important;
  border: none !important;
}

/* ==========================================
   7. 强制降低转账气泡高度
   ========================================== */
.msg-transfer-card {
  padding: 2px 14px !important; /* padding 不允许负数，已修正为最小合法极限 */ 
  min-height: 0 !important; 
}

.msg-transfer-amount {
  font-size: 16px !important; 
  line-height: 1.2 !important;
}

.msg-transfer-card hr, 
.msg-transfer-divider {
  margin: -2px 0 !important; 
}

/* ==========================================
   8. 顶栏样式设置
   ========================================== */
:root {
  --chat-header-bg: #F1F1F1;
  --chat-header-title-color: #CF9B48;
  --chat-header-title-size: 16px; 

  --info-btn-icon: url('https://img.heliar.top/file/1779095667747_retouch_2026051817092494.png');
  --btn-info-scale: 0.8; 
  --btn-info-translate-x: 0px;  
  --btn-info-translate-y: 1px;  
}

.header-avatar-container {
  display: none !important;
}

.header-btn-phone, 
.header-btn-video {
  opacity: 0 !important;
}

.chat-header-title {
  position: relative !important; 
  overflow: visible !important; 
  transform: translate(0px, -5px) !important;
}

.chat-header-title::before {
  content: "";
  position: absolute;
  background: url('https://img.heliar.top/file/1779095674833_retouch_2026051817121030.png') no-repeat left center/contain;
  pointer-events: none; 
  width: 80px;  
  height: 15px; 
  left: 0px;      
  bottom: -10px;  
}

.chat-header-title::after {
  content: "";
  position: absolute;
  background: url('https://img.heliar.top/file/1779095667209_retouch_2026051817082930.png') no-repeat center/contain;
  pointer-events: none;
  width: 80px; 
  height: 22px; 
  right: -90px;   
  top: -2px;      
}
/* ==========================================
   在 AI/发送 按钮的粉色贴图正中心写上白色“发送”
   ========================================== */
.input-btn-ai::before, .send-btn-custom::before {
  content: "发送" !important;
  position: absolute;
  top: 50%; 
  left: 50%;
  transform: translate(-50%, -50%); 

  color: #FFFFFF !important;      /* 纯白文字 */
  font-size: 12px !important;     /* 字体大小（根据贴图大小调整） */
  font-weight: bold !important;   /* 字体加粗 */
  letter-spacing: 1px !important; /* 微微拉开一点字间距更好看 */
  margin-left: 1px !important;    /* 修正间距带来的轻微偏移，保证绝对居中 */

  z-index: 10 !important;         /* 强制浮在粉色贴图的上方 */
  pointer-events: none !important;/* 保证文字不会阻挡手指的点击 */
  white-space: nowrap !important; /* 防止文字换行 */
}
* =========================================
   1. 微方圆气泡（整体缩小 + 高度压缩，仅上下粉色晕染）
========================================= */
:root {
  /* 我方气泡 */
  --bubble-me-bg: #fffbfb;             /* 极浅粉白底 */
  --bubble-me-color: #5c4b4b;          /* 暖灰文字 */

  /* 👇 【重点缩小】上下边距极限压缩为6px，左右14px，高度大幅变矮 */
  --bubble-me-padding: 6px 14px;       
  /* 👇 【整体缩小】字号等比例缩小 */
  --bubble-me-font-size: 13px;         

  --bubble-me-border: none;            

  /* 配合小气泡，阴影的厚度也稍微减弱了一点点，显得更精致 */
  --bubble-me-shadow: 
    inset 0 3px 5px -2px #fadce3,      /* 顶部粉色内阴影 */
    inset 0 -3px 5px -2px #fadce3;     /* 底部粉色内阴影 */

  /* 👇 【重点修改】圆角改为 10px，介于“大圆润”和“纯直角”之间，完美的微方圆 */
  --bubble-me-radius: 10px;            
  --bubble-me-radius-first: 10px;
  --bubble-me-radius-mid: 10px;
  --bubble-me-radius-last: 10px;

  /* 对方气泡（同步缩小） */
  --bubble-them-bg: #fffbfb;
  --bubble-them-color: #5c4b4b;
  --bubble-them-padding: 6px 14px;
  --bubble-them-font-size: 13px;

  --bubble-them-border: none;
  --bubble-them-shadow: 
    inset 0 3px 5px -2px #fadce3,
    inset 0 -3px 5px -2px #fadce3;

  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px;
  --bubble-them-radius-mid: 10px;
  --bubble-them-radius-last: 10px;
}

/* 必须设置相对定位和允许溢出，颜文字才不会被切掉 */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* =========================================
   2. 气泡顶部颜文字装饰
========================================= */

/* 给气泡左上角加上悬浮的颜文字 */
.bubble-me-custom::before,
.bubble-them-custom::before {
  content: ",,0-0,,";           
  position: absolute;
  top: -12px;                   /* 配合变矮的气泡微调了高度 */
  left: 8px;                    /* 配合变方的圆角微调了位置 */
  font-size: 11px;              /* 颜文字也等比例变小一点点 */
  color: #b8acac;               
  font-weight: 500;
  letter-spacing: 1px;          
  pointer-events: none;
}

/* 增加消息顶部间距，给小颜文字留出空间 */
.chat-message-list-custom .msg-bubble-container {
  margin-top: 5px !important;
  margin-bottom: 5px !important;
}


/* =========================================
   3. 特殊消息（图片/卡片等）自动隐藏装饰
========================================= */

/* 让特殊气泡本体变透明、无边框、无阴影 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"]),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"]) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 隐藏颜文字 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before {
  display: none !important;
}
/* =========================================
   对方专属头像框设置
   ========================================= */
/* 确保头像容器可以作为绝对定位的参照物，并且允许头像框超出边界 */
.msg-avatar-them-container {
  position: relative !important;
  overflow: visible !important;
}

/* 使用伪元素绘制头像框 */
.msg-avatar-them-container::after {
  content: "" !important;
  position: absolute !important;
  display: block !important;

  /* 🌟 1. 对方头像框图片链接 */
  background-image: url('https://i.postimg.cc/dt9PsgdP/IMG-0523.png') !important;
  background-size: 100% 100% !important; /* 让图片完全填满设定的宽高 */
  background-repeat: no-repeat !important;
  background-position: center !important;

  /* 🌟 2. 调整头像框的大小 */
  /* 如果觉得框太小，就把数值改大（比如 60px）；觉得太大就改小 */
  width: 50px !important;  
  height: 50px !important; 

  /* 🌟 3. 调整头像框的上下左右位置 */
  /* 
     top: 控制上下。负数往上移，正数往下移。
     left: 控制左右。负数往左移，正数往右移。
     (根据您头像原本的大小，这里需要微调，让框刚好套住头像)
  */
  top: -6px !important;   
  left: -8px !important;  

  /* 确保头像框盖在头像上面，且不会阻挡点击 */
  z-index: 10 !important;
  pointer-events: none !important;
}

/* =========================================
   我方(主人)专属头像框设置
   ========================================= */
/* 确保我方头像显示，并作为定位参照物 */
.msg-avatar-me-container {
  display: block !important; /* 🌟 把之前隐藏的头像放出来 */
  position: relative !important;
  overflow: visible !important;
}

/* 使用伪元素绘制主人的头像框 */
.msg-avatar-me-container::after {
  content: "" !important;
  position: absolute !important;
  display: block !important;

  /* 🌟 1. 我的的头像框图片链接 */
  background-image: url('https://i.postimg.cc/qvBw85FH/IMG-0521.png') !important;
  background-size: 100% 100% !important; /* 让图片完全填满设定的宽高 */
  background-repeat: no-repeat !important;
  background-position: center !important;

  /* 🌟 2. 调整头像框的大小 */
  /* 如果觉得框太小，就把数值改大；觉得太大就改小 */
  width: 50px !important;  
  height: 50px !important; 

  /* 🌟 3. 调整头像框的上下左右位置 */
  /* 
     top: 控制上下。负数往上移，正数往下移。
     left: 控制左右。负数往左移，正数往右移。
  */
  top: -7px !important;   
  left: -5px !important;  

  /* 确保头像框盖在头像上面，且不会阻挡点击 */
  z-index: 10 !important;
  pointer-events: none !important;
}

